import { describe, expect, it, vi, beforeEach } from 'vitest';
import { appendChangeLog } from './repo.js';
import type { ChangeLogEntry } from '@asohav/shared';

/* The changelog table has `id uuid primary key default gen_random_uuid()`. The old code generated
   its own string id (e.g. 'log-2mks435g') and included it in every insert, which Postgres rejects
   with "invalid input syntax for type uuid" — every write's audit-log call threw.

   This file mocks the Supabase client to verify the insert payload is clean: no explicit `id`,
   every column the changelog table declares is present in the correct snake_case form, and errors
   propagate rather than silently swallowed. These tests fail if someone removes the fix (puts the
   explicit id back). */

vi.mock('./supabase.js', () => ({
  supabaseAdmin: {
    from: (_table: string) => ({
      insert: vi.fn(),
      select: vi.fn(),
      update: vi.fn(),
      upsert: vi.fn(),
      delete: vi.fn(),
      eq: vi.fn().mockReturnThis(),
      order: vi.fn().mockReturnThis(),
      limit: vi.fn().mockReturnThis(),
      maybeSingle: vi.fn().mockReturnThis(),
      in: vi.fn().mockReturnThis(),
      ilike: vi.fn().mockReturnThis(),
      maybeSingle: vi.fn().mockReturnThis(),
    }),
    auth: {
      admin: {
        listUsers: vi.fn(),
        getUserById: vi.fn(),
        generateLink: vi.fn(),
        updateUserById: vi.fn(),
      },
    },
  },
}));

const supabase = vi.mocked(await import('./supabase.js')).supabaseAdmin;
const insertMock = vi.fn();
vi.mocked(supabase.from('changelog').insert).mockImplementation(insertMock);

/* The vi.mock is Hoisted, but the `from('changelog').insert()` call above captures the *current*
   vi.fn(). We need the mock on the chained object, not on `from`'s return at the time vi.mock
   runs. Since `from` returns a fresh object each time, we configure the mock via a resolver. */

beforeEach(() => {
  vi.resetAllMocks();
});

describe('appendChangeLog', () => {
  it('does not include an explicit id key in the insert payload', async () => {
    insertMock.mockReturnValue({ data: null, error: null });

    await appendChangeLog({
      Who: 'admin',
      Action: 'update',
      Collection: 'virtues',
      ObjectId: 'v-might',
      ObjectName: 'Might',
      Before: { Name: 'Might' },
      After: { Name: 'Might' },
    });

    expect(insertMock).toHaveBeenCalled();
    const payload = insertMock.mock.calls[0][0] as Record<string, unknown>;
    expect('id' in payload).toBe(false);
  });

  it('includes every changelog table column mapped to snake_case', async () => {
    const at = '2026-01-01T00:00:00.000Z';
    // Replace nowIso() at module level by mocking it — but that's messy. Instead, capture
    // the payload and check the keys we can.
    insertMock.mockReturnValue({ data: null, error: null });

    await appendChangeLog({
      Who: 'admin',
      Action: 'update',
      Collection: 'virtues',
      ObjectId: 'v-might',
      ObjectName: 'Might',
      Before: { foo: 'bar' },
      After: { foo: 'baz' },
    });

    expect(insertMock).toHaveBeenCalled();
    const payload = insertMock.mock.calls[0][0] as Record<string, unknown>;
    const keys = Object.keys(payload).sort();

    // The changelog columns: at, who, action, collection, object_id, object_name, before, after
    // id is deliberately absent (server-side default).
    expect(keys).toEqual(['action', 'after', 'at', 'before', 'collection', 'object_id', 'object_name', 'who']);
  });

  it('propagates the error if the insert call rejects', async () => {
    insertMock.mockRejectedValue(new Error('db connection failed'));

    await expect(appendChangeLog({
      Who: 'admin',
      Action: 'create',
      Collection: 'items',
      ObjectId: 'i-lantern',
      ObjectName: 'Lantern',
      Before: null,
      After: { Name: 'Lantern' },
    })).rejects.toThrow('db connection failed');
  });
});

import { describe, expect, it, vi, beforeEach } from 'vitest';
import type { ChangeLogEntry } from '@asohav/shared';

/* The changelog table has `id uuid primary key default gen_random_uuid()`. The old code
   generated its own string id (e.g. 'log-2mks435g') and included it in every insert, which
   Postgres rejects with "invalid input syntax for type uuid" — every write's audit-log call
   threw. These tests mock `supabaseAdmin.from()` to capture the insert payload without hitting
   a real database. */

let insertPayload: Record<string, unknown> | null = null;

vi.mock('./supabase.js', () => ({
  supabaseAdmin: {
    from: (_table: string) => ({
      insert(payload: Record<string, unknown>) {
        insertPayload = payload;
        return { data: null, error: null };
      },
      select() { return { eq: () => ({ maybeSingle: () => ({ data: null, error: null }) }) }; },
      update() { return { eq: () => { return { data: null, error: null }; } }; },
      upsert() { return { data: null, error: null }; },
      delete() { return { eq: () => ({ data: null, error: null }) }; },
    }),
    auth: {
      admin: {
        listUsers: () => ({ data: { users: [] }, error: null }),
        getUserById: () => ({ data: { user: null }, error: null }),
        generateLink: () => ({ data: { properties: null }, error: null }),
        updateUserById: () => ({ data: { user: null }, error: null }),
      },
    },
  },
}));

beforeEach(() => {
  vi.resetAllMocks();
  insertPayload = null;
});

describe('appendChangeLog', () => {
  it('does not include an explicit id key in the insert payload', async () => {
    const { appendChangeLog } = await import('./repo.js');

    await appendChangeLog({
      Who: 'admin',
      Action: 'update',
      Collection: 'virtues',
      ObjectId: 'v-might',
      ObjectName: 'Might',
      Before: { Name: 'Might' },
      After: { Name: 'Might' },
    } as Omit<ChangeLogEntry, 'Id' | 'At'>);

    expect(insertPayload).not.toBeNull();
    expect('id' in insertPayload!).toBe(false);
  });

  it('includes every changelog table column mapped to snake_case', async () => {
    const { appendChangeLog } = await import('./repo.js');

    await appendChangeLog({
      Who: 'admin',
      Action: 'create',
      Collection: 'items',
      ObjectId: 'i-lantern',
      ObjectName: 'Lantern',
      Before: null,
      After: { Name: 'Lantern' },
    } as Omit<ChangeLogEntry, 'Id' | 'At'>);

    expect(insertPayload).not.toBeNull();
    const keys = Object.keys(insertPayload!).sort();

    // changelog columns: action, after, at, before, collection, object_id, object_name, who
    // id is deliberately absent so gen_random_uuid() supplies it.
    expect(keys).toEqual(['action', 'after', 'at', 'before', 'collection', 'object_id', 'object_name', 'who']);
  });

  it('propagates the error if the insert call rejects', async () => {
    const { supabaseAdmin } = await import('./supabase.js');
    vi.spyOn(supabaseAdmin, 'from').mockReturnValue({
      insert: () => { throw new Error('db connection failed'); },
      select: () => ({ eq: () => ({ maybeSingle: () => ({ data: null, error: null }) }) }),
      update: () => ({ eq: () => ({ data: null, error: null }) }),
      upsert: () => ({ data: null, error: null }),
      delete: () => ({ eq: () => ({ data: null, error: null }) }),
    } as any);

    const { appendChangeLog } = await import('./repo.js');

    await expect(appendChangeLog({
      Who: 'admin',
      Action: 'delete',
      Collection: 'virtues',
      ObjectId: 'v-might',
      ObjectName: 'Might',
      Before: { Name: 'Might' },
      After: null,
    } as Omit<ChangeLogEntry, 'Id' | 'At'>)).rejects.toThrow('db connection failed');
  });
});

